/*==============================================================
  CineChef - Fase 3c: recetas, tanda 4 de 4
  25 recetas nuevas; tanda final sin modificar las anteriores.
  Solo utiliza ingredientes cargados en 03b_ingredients.sql.
==============================================================*/
USE CineChefDB;
GO

INSERT INTO dbo.Recipes (Name, Description, PrepMin, Difficulty, Servings)
SELECT source.Name, source.Description, source.PrepMin, source.Difficulty, source.Servings
FROM (VALUES
(N'Crispy Chicken Lemon Salad',N'Crisp lettuce, chicken breast, cucumber, Parmesan, and lemon come together in a bright salad with a satisfying savory finish. It feels fresh but substantial, ideal for a clear-minded lunch or a relaxed evening when the table should look colorful and inviting.',30,1,4),
(N'Moroccan Carrot Apricot Couscous',N'Carrots, couscous, dried apricots, cumin, and parsley create a fragrant bowl with gentle sweetness and warm North African character. The grains stay light while the fruit deepens the mood, making a generous, sunlit meal for sharing stories around the table.',40,1,4),
(N'Creamy Corn Potato Chowder',N'Corn, potato, milk, onion, and bacon simmer into a thick, golden chowder with a familiar kitchen aroma. It is comforting without being complicated, the sort of bowl that makes a windy evening feel sheltered and gives everyone a reason to linger over dinner.',55,1,6),
(N'Tuscan Kale Bean Pasta',N'Pasta, kale, kidney beans, tomato, and Parmesan make a rustic bowl with deep color and satisfying texture. The sauce is bright and savory, while the beans add substance. It feels like a relaxed supper in a warm kitchen, generous enough for a second serving.',45,1,4),
(N'Prawn Coconut Lime Soup',N'Prawns, coconut milk, lime, mushrooms, and curry powder form a fragrant soup with gentle tropical warmth. The broth is silky and lively rather than heavy, creating a small escape for a rainy night when dinner should feel bright, soothing, and a little adventurous.',35,2,4),
(N'Stuffed Zucchini Beef Boats',N'Zucchini filled with ground beef, tomato, onion, and Cheddar bake until tender beneath a golden topping. The dish feels playful and homely at once, perfect for a family table where familiar flavors can arrive in a new shape and everyone wants to try one.',65,2,4),
(N'Apple Raisin Rice Pilaf',N'Rice, apple, raisins, cinnamon, and almonds create a fragrant pilaf that balances soft fruit with gentle crunch. It has a calm, autumnal personality and works beautifully as a light main or a festive side, bringing warmth to an evening without overwhelming the table.',40,1,4),
(N'Spinach Feta Tortilla Fold',N'Tortillas folded around spinach, feta, eggs, bell pepper, and parsley become crisp outside and tender inside. The flavors are bright and familiar, making this an easy brunch or late supper for a day when cooking should feel playful, quick, and pleasantly unplanned.',25,1,3),
(N'Vegetable Tahini Quinoa Bowl',N'Quinoa, broccoli, chickpeas, tahini, and lemon build a creamy, fresh bowl with plenty of contrast. The grains and legumes feel grounding, while the citrus keeps the dish lively. It is a calm, nourishing meal for resetting after a busy week.',35,1,4),
(N'Cod Pea Cream Bake',N'Cod, peas, cream, potato, and parsley bake into a soft, comforting dish with a delicate seaside flavor. The top turns lightly golden while the center stays tender, creating a quiet supper for cool weather, soft lighting, and an appetite for something reassuring.',60,2,4),
(N'Chicken Paprika Rice Pot',N'Chicken thighs, rice, bell pepper, tomato paste, and paprika cook together in one fragrant pot. The rice absorbs the savory juices and the peppers add sweetness, making dinner feel abundant and cheerful while keeping the preparation pleasantly simple.',55,2,4),
(N'Avocado Tomato Corn Salsa Bowl',N'Avocado, tomato, corn, black beans, and lime make a cool bowl with bright colors and a lively, fresh finish. It is quick enough for lunch yet satisfying enough for dinner, a cheerful choice when the mood calls for sunshine, crunch, and no unnecessary fuss.',20,1,3),
(N'Roasted Beetless Root Vegetable Plate',N'Sweet potato, carrot, cauliflower, olive oil, and rosemary roast into a colorful plate with caramelized edges and a comforting herbal aroma. It feels generous and rustic, a relaxed vegetarian centerpiece for evenings when the oven can turn simple vegetables into something special.',50,1,4),
(N'Smoky Turkey Tomato Toast',N'Bread topped with turkey breast, tomato, mustard, Cheddar, and paprika makes a warm toast with smoky, sharp, and creamy layers. It is a practical supper with the spirit of a café snack, perfect for a quiet film or a late return home.',20,1,2),
(N'Creamy Pea Parmesan Spaghetti',N'Spaghetti, peas, cream, Parmesan, and garlic form a pale green sauce with a soft, springlike flavor. The dish is quick but feels polished, offering a gentle comfort that suits a date night, a quiet celebration, or a peaceful meal alone.',30,1,3),
(N'Warm Banana Coconut Oats',N'Oats, banana, coconut milk, honey, and cinnamon make a warm breakfast with a soft tropical fragrance. The bowl is creamy and comforting without being heavy, giving slow mornings a welcoming rhythm and turning an ordinary start into a small ritual.',20,1,2),
(N'Herbed Lamb Pepper Skewers',N'Lamb mince shaped with bell pepper, onion, parsley, cumin, and olive oil becomes fragrant, browned, and easy to share. The flavors feel festive and sociable, suited to a balcony dinner or a lively evening when everyone wants food that invites conversation.',45,2,4),
(N'Broccoli Cheddar Potato Cakes',N'Potato, broccoli, Cheddar, eggs, and breadcrumbs form golden cakes with a soft center and crisp edges. They are familiar, cheerful, and easy to pass around, making a comforting lunch or a casual supper when leftovers deserve a delicious second act.',40,1,4),
(N'Tuna White Beanless Tomato Salad',N'Tuna, tomato, cucumber, olives, and lemon create a crisp salad with a clean Mediterranean mood. The fish brings satisfying depth while the vegetables stay bright, making the bowl ideal for warm afternoons, simple lunches, and evenings when freshness matters.',15,1,2),
(N'Sweet Peach Yogurt Cream',N'Peach, yogurt, cream, honey, and vanilla make a cool dessert with a delicate fragrance and soft, summery sweetness. It feels indulgent but light, a graceful ending for a long meal or a quiet treat when the evening needs a little gentleness.',15,1,4),
(N'Garlic Shrimp Tomato Spaghetti',N'Shrimp, spaghetti, tomato, garlic, parsley, and olive oil create a quick pasta with bright coastal energy. The sauce is lively and fragrant, while the seafood stays tender. It is a confident weeknight dinner that brings a little celebration to the table.',35,2,4),
(N'Roasted Cauliflower Tahini Plate',N'Cauliflower roasted with tahini, lemon, chickpeas, paprika, and parsley becomes a warm plate with nutty depth and bright citrus. It feels both rustic and considered, a satisfying vegetarian meal for evenings when comfort should still taste fresh and modern.',45,1,4),
(N'Beef Mushroom Tomato Skillet',N'Ground beef, mushrooms, tomato paste, onion, and oregano cook into a savory skillet with a rich aroma and tender texture. It is an uncomplicated comfort meal for busy nights, generous enough to share and bold enough to make a quiet dinner feel complete.',35,1,4),
(N'Orange Berry Yogurt Parfait',N'Orange, strawberries, blueberries, yogurt, and honey layer into a bright parfait with creamy and juicy textures. It tastes like a clear morning and looks festive without effort, making it a gentle breakfast, a cheerful dessert, or a fresh pause between heavier meals.',10,1,4),
(N'Squid Olive Couscous Pan',N'Squid, couscous, olives, tomato, lemon, and parsley make a quick pan with briny Mediterranean character. The seafood stays delicate and the grains absorb the bright juices, creating a lively shared dinner for nights when the table should feel close to the sea.',35,2,4)
) AS source (Name,Description,PrepMin,Difficulty,Servings)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Recipes AS target WHERE target.Name=source.Name);
GO

